"""CODEOWNERS and harness deny rules, generated from [risk.t2] in agentdev.toml.

One list decides what needs a human: the risk tier reads it, CODEOWNERS makes
GitHub ask for an owner's review of it, and an agent's harness is told not to
edit it. Generating the other two removes "keep these in sync" by hand.
"""

from __future__ import annotations

import json

HEADER = """\
# Generated by `agentctl codeowners` from [risk.t2] in agentdev.toml. Do not edit:
# change agentdev.toml and run it again. CI fails when this file is out of date.
# Enforced by the `main` ruleset (require_code_owner_review). Only people are
# owners; an agent's GitHub App never is.
"""

GROUPS = [
    ("human_gated", "Product decisions: specs, sprints, product documents."),
    ("guardrails", "The guardrails themselves."),
    ("dependency_manifests", "Dependencies: manifests and lock files, anywhere in the tree."),
    ("high_risk", "High-risk code."),
]


def codeowners_pattern(glob: str) -> str:
    """A risk glob as a CODEOWNERS pattern. Anchored at the root unless it starts with **/."""
    if glob.startswith("**/"):
        return glob
    return "/" + glob.lstrip("/")


def codeowners(cfg: dict) -> str:
    owners = " ".join(f"@{login}" for login in cfg["roles"].get("directors", []))
    if not owners:
        raise SystemExit("[roles] directors is empty in agentdev.toml: CODEOWNERS needs at least one person")
    t2 = cfg["risk"]["t2"]
    lines = [HEADER]
    for group, title in GROUPS:
        patterns = t2.get(group, [])
        if not patterns:
            continue
        lines.append(f"# {title}")
        width = max(len(codeowners_pattern(p)) for p in patterns) + 1
        lines += [f"{codeowners_pattern(p):<{width}}{owners}" for p in patterns]
        lines.append("")
    return "\n".join(lines)


def harness_settings(cfg: dict, kind: str) -> str:
    """Claude Code settings for a stage's sandbox: no edits to guardrails, and for
    story stages none to the product documents either. A second, soft layer under
    the token scope and the ruleset."""
    t2 = cfg["risk"]["t2"]
    protected = list(t2.get("guardrails", []))
    if kind == "story":
        protected += t2.get("human_gated", [])
    elif kind != "spec":
        raise SystemExit(f"unknown settings kind: {kind}")
    return json.dumps({"permissions": {"deny": [f"Edit({p})" for p in protected]}}, indent=2) + "\n"
